import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Spinner, Alert, Badge } from 'react-bootstrap';
import { useParams, Link } from 'react-router-dom';
import { postsAPI } from '../../services/api';

const PostDetail = () => {
  const [post, setPost] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const { id } = useParams();

  useEffect(() => {
    fetchPost();
  }, [id]);

  const fetchPost = async () => {
    try {
      setLoading(true);
      const response = await postsAPI.getById(id);
      setPost(response.data);
    } catch (err) {
      setError('Failed to load post');
      console.error('Error fetching post:', err);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <Container className="text-center py-5">
        <Spinner animation="border" role="status">
          <span className="visually-hidden">Loading...</span>
        </Spinner>
      </Container>
    );
  }

  if (error) {
    return (
      <Container className="py-5">
        <Alert variant="danger">{error}</Alert>
        <Link to="/posts" className="btn btn-primary">Back to Posts</Link>
      </Container>
    );
  }

  if (!post) {
    return (
      <Container className="py-5">
        <Alert variant="warning">Post not found</Alert>
        <Link to="/posts" className="btn btn-primary">Back to Posts</Link>
      </Container>
    );
  }

  return (
    <Container className="py-5">
      <Row>
        <Col lg={8} className="mx-auto">
          <Card>
            {post.image && (
              <Card.Img 
                variant="top" 
                src={`http://127.0.0.1:8000/storage/${post.image}`}
                style={{ height: '400px', objectFit: 'cover' }}
              />
            )}
            <Card.Body>
              <div className="mb-3">
                <Link to="/posts" className="text-decoration-none">
                  ← Back to Posts
                </Link>
              </div>

              <Card.Title as="h1" className="mb-3">
                {post.title}
              </Card.Title>

              <div className="mb-3 d-flex align-items-center gap-3">
                <small className="text-muted">
                  By <strong>{post.creator?.name}</strong>
                </small>
                <small className="text-muted">
                  {new Date(post.created_at).toLocaleDateString('en-US', {
                    year: 'numeric',
                    month: 'long',
                    day: 'numeric'
                  })}
                </small>
                <Badge bg="success">{post.status}</Badge>
              </div>

              <div 
                className="post-content"
                dangerouslySetInnerHTML={{ __html: post.content }}
                style={{ lineHeight: '1.8' }}
              />

              {post.published_at && (
                <div className="mt-4 pt-3 border-top">
                  <small className="text-muted">
                    Published on {new Date(post.published_at).toLocaleDateString('en-US', {
                      year: 'numeric',
                      month: 'long',
                      day: 'numeric',
                      hour: '2-digit',
                      minute: '2-digit'
                    })}
                  </small>
                </div>
              )}
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default PostDetail;
